        if len(external) != 1:
            return None
        pre = external[0]
        if self.flow.succs[pre] != [header]:
            return None
        return pre

    # -- planning -----------------------------------------------------------

    def _plan(self):
        """Decide every move before constructing the output.

        Returns ``moves`` mapping an instruction to ``(origin, preheader)``.

